import sys
import math


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = [abs(int(x)) for x in line.split()]
        if not nums:
            continue
        g = abs(nums[0])
        l = nums[0]
        for n in nums[1:]:
            g = math.gcd(g, n)
            l = l * n // math.gcd(l, n)
        print(g, l)


if __name__ == "__main__":
    main()
